package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.security.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.dto.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.access.prepost.PreAuthorize;
/** Durable print requests are created after invoice confirmation returns to the caller. */
@Service
public class BillingPrintService {
 private final JdbcTemplate jdbc;private final FacturaVentaRepository facturas;private final PrintAgentRoutingService routing;private final FacturaVentaPdfService pdf;private final AgenteImpresionRepository agentes;private final AuditoriaService audit;
 public BillingPrintService(JdbcTemplate jdbc,FacturaVentaRepository facturas,PrintAgentRoutingService routing,FacturaVentaPdfService pdf,AgenteImpresionRepository agentes,AuditoriaService audit){this.jdbc=jdbc;this.facturas=facturas;this.routing=routing;this.pdf=pdf;this.agentes=agentes;this.audit=audit;}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and (hasAuthority('facturas.pdf') or hasAuthority('facturas.configurar_impresion'))")
 public boolean mostrarPdf(){var p=TenantContext.principalActual();return jdbc.query("select show_pdf_on_print from billing_print_settings where tenant_id=? and empresa_id=?",(rs,n)->rs.getBoolean(1),p.tenantId(),p.empresaId()).stream().findFirst().orElse(true);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.configurar_impresion')")
 public void configurar(boolean mostrar){var p=TenantContext.principalActual();jdbc.update("insert into billing_print_settings(tenant_id,empresa_id,show_pdf_on_print) values(?,?,?) on conflict(tenant_id,empresa_id) do update set show_pdf_on_print=excluded.show_pdf_on_print",p.tenantId(),p.empresaId(),mostrar);audit.registrar("BillingPrintSettingsChanged","Empresa",p.empresaId(),"{}");}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.pdf')")
 public UUID solicitar(UUID facturaId,UUID intento){var p=TenantContext.principalActual();var f=facturas.findByIdAndTenantIdAndEmpresaId(facturaId,p.tenantId(),p.empresaId()).filter(x->EmpresaContext.permiteSucursal(x.getSucursalId())).orElseThrow(()->new RecursoNoEncontradoException("Factura no encontrada."));var existentes=jdbc.query("select id from billing_print_jobs where tenant_id=? and empresa_id=? and idempotency_key=? and document_id=?",(r,n)->r.getObject(1,UUID.class),p.tenantId(),p.empresaId(),intento,facturaId);if(!existentes.isEmpty())return existentes.getFirst();UUID agent=routing.resolver(f.getCajaId()),id=UUID.randomUUID();byte[] documento=pdf.generarParaImpresion(facturaId).contenido();if(documento.length>8_000_000)throw new ReglaNegocioException("El documento excede el tamaño permitido para impresión.");jdbc.update("insert into billing_print_jobs(id,tenant_id,empresa_id,branch_id,cash_register_id,agent_id,document_id,idempotency_key,document_pdf) values(?,?,?,?,?,?,?,?,?) on conflict(tenant_id,empresa_id,idempotency_key) do nothing",id,p.tenantId(),p.empresaId(),f.getSucursalId(),f.getCajaId(),agent,facturaId,intento,documento);audit.registrar("PrintJobCreated","PrintJob",id,detalle(p.tenantId(),f.getSucursalId(),f.getCajaId(),agent));return jdbc.queryForObject("select id from billing_print_jobs where tenant_id=? and empresa_id=? and idempotency_key=? and document_id=?",UUID.class,p.tenantId(),p.empresaId(),intento,facturaId);}
 private com.citacloud.springboot.contacloud.app.models.AgenteImpresion activo(PrintAgentPrincipal p){return agentes.bloquear(p.agentId(),p.tenantId(),p.companyId()).filter(a->a.getEstado()==com.citacloud.springboot.contacloud.app.models.EstadoAgenteImpresion.ACTIVE&&a.getCajaId()!=null).orElseThrow(VinculacionAgenteException::new);}
 @Transactional @PreAuthorize("hasAuthority('PRINT_AGENT')")
 public Optional<TrabajoImpresionDto> siguiente(PrintAgentPrincipal p){var a=activo(p);UUID claim=UUID.randomUUID();var jobs=jdbc.query("select id from billing_print_jobs where tenant_id=? and empresa_id=? and branch_id=? and cash_register_id=? and agent_id=? and status='PENDING' order by created_at,id limit 1 for update skip locked",(r,n)->r.getObject(1,UUID.class),p.tenantId(),p.companyId(),a.getSucursalId(),a.getCajaId(),a.getId());if(jobs.isEmpty())return Optional.empty();UUID id=jobs.getFirst();jdbc.update("update billing_print_jobs set status='PROCESSING',claim_id=?,claimed_at=current_timestamp where id=? and tenant_id=? and empresa_id=?",claim,id,p.tenantId(),p.companyId());byte[] bytes=jdbc.queryForObject("select document_pdf from billing_print_jobs where id=? and tenant_id=? and empresa_id=?",byte[].class,id,p.tenantId(),p.companyId());return Optional.of(new TrabajoImpresionDto(id,claim,bytes));}
 @Transactional @PreAuthorize("hasAuthority('PRINT_AGENT')")
 public void completar(PrintAgentPrincipal p,UUID id,UUID claim,boolean printed){var a=activo(p);int count=jdbc.update("update billing_print_jobs set status=? where id=? and claim_id=? and tenant_id=? and empresa_id=? and branch_id=? and cash_register_id=? and agent_id=? and status='PROCESSING'",printed?"PRINTED":"FAILED",id,claim,p.tenantId(),p.companyId(),a.getSucursalId(),a.getCajaId(),a.getId());if(count!=1){Integer already=jdbc.queryForObject("select count(*) from billing_print_jobs where id=? and claim_id=? and tenant_id=? and empresa_id=? and agent_id=? and cash_register_id=? and status=?",Integer.class,id,claim,p.tenantId(),p.companyId(),a.getId(),a.getCajaId(),printed?"PRINTED":"FAILED");if(already!=null&&already==1)return;throw new RecursoNoEncontradoException("Trabajo no encontrado.");}audit.registrarPara(p.companyId(),null,printed?"PrintJobPrinted":"PrintJobFailed","PrintJob",id,detalle(p.tenantId(),a.getSucursalId(),a.getCajaId(),a.getId()));}
 private static String detalle(UUID tenant,UUID branch,UUID caja,UUID agent){return "{\"traceId\":\""+com.citacloud.springboot.contacloud.app.errors.TraceContext.currentOrCreate()+"\",\"tenantId\":\""+tenant+"\",\"branchId\":\""+branch+"\",\"cashRegisterId\":\""+caja+"\",\"agentId\":\""+agent+"\"}";}
}
